const { useState, useRef, useEffect, useCallback } = React;

function TrashIcon({ className = "icon" }) {
  return (
    <svg className={className} viewBox="0 0 24 24" fill="none" stroke="currentColor"
         strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M3 6h18" />
      <path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
      <path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6" />
      <path d="M10 11v6" />
      <path d="M14 11v6" />
    </svg>
  );
}

function DownloadIcon() {
  return (
    <svg className="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor"
         strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" />
      <polyline points="7 10 12 15 17 10" />
      <line x1="12" y1="15" x2="12" y2="3" />
    </svg>
  );
}

function ShareIcon() {
  return (
    <svg className="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor"
         strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <circle cx="18" cy="5" r="3" />
      <circle cx="6" cy="12" r="3" />
      <circle cx="18" cy="19" r="3" />
      <line x1="8.59" y1="13.51" x2="15.42" y2="17.49" />
      <line x1="15.41" y1="6.51" x2="8.59" y2="10.49" />
    </svg>
  );
}

function ConfirmDeleteDialog({ open, fileName, onCancel, onConfirm }) {
  const dialogRef = useRef(null);
  const cancelBtnRef = useRef(null);

  useEffect(() => {
    const dlg = dialogRef.current;
    if (!dlg) return;
    if (open && !dlg.open) {
      dlg.showModal();
      // Focus the safe (non-destructive) action by default.
      requestAnimationFrame(() => cancelBtnRef.current?.focus());
    } else if (!open && dlg.open) {
      dlg.close();
    }
  }, [open]);

  // Handle native close (Escape, backdrop close, etc.)
  useEffect(() => {
    const dlg = dialogRef.current;
    if (!dlg) return;
    const handleClose = () => {
      if (open) onCancel();
    };
    const handleCancel = (e) => {
      // Allow default Escape behavior; ensure state syncs.
      // No preventDefault — Escape should close.
    };
    dlg.addEventListener("close", handleClose);
    dlg.addEventListener("cancel", handleCancel);
    return () => {
      dlg.removeEventListener("close", handleClose);
      dlg.removeEventListener("cancel", handleCancel);
    };
  }, [open, onCancel]);

  // Click on backdrop closes the dialog.
  const handleBackdropClick = (e) => {
    if (e.target === dialogRef.current) onCancel();
  };

  return (
    <dialog
      ref={dialogRef}
      className="modal"
      aria-labelledby="confirm-delete-title"
      aria-describedby="confirm-delete-desc"
      onClick={handleBackdropClick}
    >
      <div className="modal-panel">
        <div className="modal-body">
          <span className="modal-icon" aria-hidden="true">
            <TrashIcon className="" />
          </span>
          <h2 id="confirm-delete-title" className="modal-title">
            Delete this image?
          </h2>
          <p id="confirm-delete-desc" className="modal-desc">
            This image will be permanently removed from your library. This action can't be undone.
          </p>
          <div className="modal-filename" aria-label="File to delete">{fileName}</div>
        </div>
        <div className="modal-actions">
          <button
            ref={cancelBtnRef}
            type="button"
            className="btn"
            onClick={onCancel}
          >
            Cancel
          </button>
          <button type="button" className="btn btn-danger" onClick={onConfirm}>
            <TrashIcon />
            Delete image
          </button>
        </div>
      </div>
    </dialog>
  );
}

function StatusToast({ message }) {
  return (
    <div className={`status ${message ? "is-visible" : ""}`} role="status" aria-live="polite">
      {message}
    </div>
  );
}

function ImagePreviewPage() {
  const [dialogOpen, setDialogOpen] = useState(false);
  const [deleted, setDeleted] = useState(false);
  const [status, setStatus] = useState("");
  const triggerRef = useRef(null);

  const image = {
    src: "https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&w=1200&q=80",
    alt: "Misty mountain ridges at sunrise with warm golden light spilling across the peaks.",
    fileName: "mountains-sunrise.jpg",
    size: "3.2 MB",
    dimensions: "4032 × 3024",
    uploaded: "May 1, 2026",
  };

  const openDialog = useCallback(() => setDialogOpen(true), []);
  const closeDialog = useCallback(() => setDialogOpen(false), []);

  const confirmDelete = useCallback(() => {
    setDialogOpen(false);
    setDeleted(true);
    setStatus(`"${image.fileName}" was deleted from your library.`);
    window.setTimeout(() => setStatus(""), 4000);
  }, [image.fileName]);

  return (
    <>
      <header className="site-header">
        <div className="site-header-inner">
          <span className="brand">
            <span className="brand-mark" aria-hidden="true"></span>
            Aurora Library
          </span>
          <nav className="site-nav" aria-label="Primary">
            <ul>
              <li><a href="#" aria-current="page">Library</a></li>
              <li><a href="#">Albums</a></li>
              <li><a href="#">Shared</a></li>
              <li><a href="#">Settings</a></li>
            </ul>
          </nav>
        </div>
      </header>

      <main id="main">
        <p className="breadcrumb">
          <a href="#">Library</a> &nbsp;/&nbsp; <span>Image preview</span>
        </p>
        <h1>{image.fileName}</h1>
        <p className="subtitle">Uploaded {image.uploaded}</p>

        <div className="preview-grid">
          <article className="image-card" aria-labelledby="image-heading">
            <h2 id="image-heading" className="visually-hidden" style={{position:"absolute",left:"-9999px"}}>
              Image preview
            </h2>
            <div className="image-frame">
              {deleted ? (
                <p style={{ color: "var(--text-muted)", padding: "2rem", textAlign: "center" }}>
                  This image has been deleted.
                </p>
              ) : (
                <img src={image.src} alt={image.alt} />
              )}
            </div>
            <div className="image-actions">
              <button type="button" className="btn">
                <DownloadIcon /> Download
              </button>
              <button type="button" className="btn">
                <ShareIcon /> Share
              </button>
              <button
                type="button"
                ref={triggerRef}
                className="btn btn-ghost trigger"
                onClick={openDialog}
                disabled={deleted}
                style={{ marginLeft: "auto", color: deleted ? undefined : "var(--danger)" }}
                aria-haspopup="dialog"
              >
                <TrashIcon /> Delete
              </button>
            </div>
          </article>

          <aside className="meta-card" aria-labelledby="details-heading">
            <h2 id="details-heading">Details</h2>
            <dl className="meta-list">
              <dt>File name</dt><dd>{image.fileName}</dd>
              <dt>Dimensions</dt><dd>{image.dimensions}</dd>
              <dt>Size</dt><dd>{image.size}</dd>
              <dt>Uploaded</dt><dd>{image.uploaded}</dd>
            </dl>
          </aside>
        </div>
      </main>

      <ConfirmDeleteDialog
        open={dialogOpen}
        fileName={image.fileName}
        onCancel={closeDialog}
        onConfirm={confirmDelete}
      />

      <StatusToast message={status} />
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<ImagePreviewPage />);

